 auto overlap=source;for(auto& a:overlap.objects){a.tool=core::Tool::Rectangle;a.filled=true;a.rect={0,0,20,20};}overlap.objects[1].hidden=true;check(core::ObjectsAt(overlap,{5,5},2)==std::vector<int>({2,0}),"overlap hits preserve topmost order and omit hidden objects");
 const std::array<POINT,4> corners{{{0,0},{159,0},{159,99},{0,99}}};auto corrected=core::CorrectPerspective(*base,corners,160,100);check(corrected.pixels==base->pixels,"identity perspective preserves exact opaque RGBA and dimensions");const std::array<POINT,4> trapezoid{{{10,5},{140,10},{150,90},{5,80}}};corrected=core::CorrectPerspective(*base,trapezoid,20,10);check(std::equal(corrected.Row(0),corrected.Row(0)+4,base->Row(5)+40)&&std::equal(corrected.Row(9)+19*4,corrected.Row(9)+20*4,base->Row(90)+150*4),"perspective maps all corner endpoints without losing source identity");auto invalid=corners;invalid[2]=invalid[0];check(Reject([&]{core::CorrectPerspective(*base,invalid,20,10);}),"nonconvex/degenerate corners reject");invalid=corners;invalid[0].x=-1;check(Reject([&]{core::CorrectPerspective(*base,invalid,20,10);})&&Reject([&]{core::CorrectPerspective(*base,corners,32768,32768);}),"outside corners and oversized perspective buffers reject before allocation");
